1	use std::io::{self, Write};
2	
3	use crate::stream::raw::{InBuffer, Operation, OutBuffer};
4	
5	// input -> [ zstd -> buffer -> writer ]
6	
7	/// Implements the [`Write`] API around an [`Operation`].
8	///
9	/// This can be used to wrap a raw in-memory operation in a write-focused API.
10	///
11	/// It can be used with either compression or decompression, and forwards the
12	/// output to a wrapped `Write`.
13	pub struct Writer<W, D> {
14	    /// Either an encoder or a decoder.
15	    operation: D,
16	
17	    /// Where we send the output of the operation.
18	    writer: W,
19	
20	    /// Offset into the buffer
21	    ///
22	    /// Only things after this matter. Things before have already been sent to the writer.
23	    offset: usize,
24	
25	    /// Output buffer
26	    ///
27	    /// Where the operation writes, before it gets flushed to the writer
28	    buffer: Vec<u8>,
29	
30	    // When `true`, indicates that nothing should be added to the buffer.
31	    // All that's left if to empty the buffer.
32	    finished: bool,
33	
34	    // When `true`, a finish has been requested (but may have been
35	    // interrupted, e.g. by a `WouldBlock` error from the writer).
36	    //
37	    // From that point on, `flush()` must keep driving the finish to
38	    // completion instead of starting a regular flush.
39	    finish_requested: bool,
40	
41	    /// When `true`, the operation just finished a frame.
42	    ///
43	    /// Only happens when decompressing.
44	    /// The context needs to be re-initialized to process the next frame.
45	    finished_frame: bool,
46	}
47	
48	impl<W, D> Writer<W, D>
49	where
50	    W: Write,
51	    D: Operation,
52	{
53	    /// Creates a new `Writer` with a fixed buffer capacity of 32KB
54	    ///
55	    /// All output from the given operation will be forwarded to `writer`.
56	    pub fn new(writer: W, operation: D) -> Self {
57	        // 32KB buffer? That's what flate2 uses
58	        Self::new_with_capacity(writer, operation, 32 * 1024)
59	    }
60	
61	    /// Creates a new `Writer` with user defined capacity.
62	    ///
63	    /// All output from the given operation will be forwarded to `writer`.
64	    pub fn new_with_capacity(
65	        writer: W,
66	        operation: D,
67	        capacity: usize,
68	    ) -> Self {
69	        Self::with_output_buffer(
70	            Vec::with_capacity(capacity),
71	            writer,
72	            operation,
73	        )
74	    }
75	
76	    /// Creates a new `Writer` using the given output buffer.
77	    ///
78	    /// The output buffer _must_ have pre-allocated capacity (its capacity will not be changed after).
79	    ///
80	    /// Usually you would use `Vec::with_capacity(desired_buffer_size)`.
81	    pub fn with_output_buffer(
82	        output_buffer: Vec<u8>,
83	        writer: W,
84	        operation: D,
85	    ) -> Self {
86	        Writer {
87	            writer,
88	            operation,
89	
90	            offset: 0,
91	            // 32KB buffer? That's what flate2 uses
92	            buffer: output_buffer,
93	
94	            finished: false,
95	            finish_requested: false,
96	            finished_frame: false,
97	        }
98	    }
99	
100	    /// Ends the stream.
101	    ///
102	    /// This *must* be called after all data has been written to finish the
103	    /// stream.
104	    ///
105	    /// If you forget to call this and just drop the `Writer`, you *will* have
106	    /// an incomplete output.
107	    ///
108	    /// Keep calling it until it returns `Ok(())`, then don't call it again.
109	    pub fn finish(&mut self) -> io::Result<()> {
110	        self.finish_requested = true;
111	        loop {
112	            // Keep trying until we're really done.
113	            self.write_from_offset()?;
114	
115	            // At this point the buffer has been fully written out.
116	
117	            if self.finished {
118	                return Ok(());
119	            }
120	
121	            // Let's fill this buffer again!
122	            self.finish_step()?;
123	        }
124	    }
125	
126	    /// Runs a single step of the finish operation.
127	    ///
128	    /// Generates the next batch of frame trailer into `self.buffer`,
129	    /// and updates `self.finished` accordingly.
130	    fn finish_step(&mut self) -> io::Result<()> {
131	        let finished_frame = self.finished_frame;
132	        let hint = self.with_buffer(|dst, op| op.finish(dst, finished_frame));
133	        self.offset = 0;
134	        // println!("Hint: {:?}\nOut:{:?}", hint, &self.buffer);
135	
136	        // We return here if zstd had a problem.
137	        // Could happen with invalid data, ...
138	        let hint = hint?;
139	
140	        if hint != 0 && self.buffer.is_empty() {
141	            // This happens if we are decoding an incomplete frame.
142	            return Err(io::Error::new(
143	                io::ErrorKind::UnexpectedEof,
144	                "incomplete frame",
145	            ));
146	        }
147	
148	        // println!("Finishing {}, {}", bytes_written, hint);
149	
150	        self.finished = hint == 0;
151	        Ok(())
152	    }
153	
154	    /// Run the given closure on `self.buffer`.
155	    ///
156	    /// The buffer will be cleared, and made available wrapped in an `OutBuffer`.
157	    fn with_buffer<F, T>(&mut self, f: F) -> T
158	    where
159	        F: FnOnce(&mut OutBuffer<'_, Vec<u8>>, &mut D) -> T,
160	    {
161	        self.buffer.clear();
162	        let mut output = OutBuffer::around(&mut self.buffer);
163	        // eprintln!("Output: {:?}", output);
164	        f(&mut output, &mut self.operation)
165	    }
166	
167	    /// Attempt to write `self.buffer` to the wrapped writer.
168	    ///
169	    /// Returns `Ok(())` once all the buffer has been written.
170	    fn write_from_offset(&mut self) -> io::Result<()> {
171	        // The code looks a lot like `write_all`, but keeps track of what has
172	        // been written in case we're interrupted.
173	        while self.offset < self.buffer.len() {
174	            match self.writer.write(&self.buffer[self.offset..]) {
175	                Ok(0) => {
176	                    return Err(io::Error::new(
177	                        io::ErrorKind::WriteZero,
178	                        "writer will not accept any more data",
179	                    ))
180	                }
181	                Ok(n) => self.offset += n,
182	                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => (),
183	                Err(e) => return Err(e),
184	            }
185	        }
186	        Ok(())
187	    }
188	
189	    /// Return the wrapped `Writer` and `Operation`.
190	    ///
191	    /// Careful: if you call this before calling [`Writer::finish()`], the
192	    /// output may be incomplete.
193	    pub fn into_inner(self) -> (W, D) {
194	        (self.writer, self.operation)
195	    }
196	
197	    /// Gives a reference to the inner writer.
198	    pub fn writer(&self) -> &W {
199	        &self.writer
200	    }
201	
202	    /// Gives a mutable reference to the inner writer.
203	    pub fn writer_mut(&mut self) -> &mut W {
204	        &mut self.writer
205	    }
206	
207	    /// Gives a reference to the inner operation.
208	    pub fn operation(&self) -> &D {
209	        &self.operation
210	    }
211	
212	    /// Gives a mutable reference to the inner operation.
213	    pub fn operation_mut(&mut self) -> &mut D {
214	        &mut self.operation
215	    }
216	
217	    /// Returns the offset in the current buffer. Only useful for debugging.
218	    #[cfg(test)]
219	    pub fn offset(&self) -> usize {
220	        self.offset
221	    }
222	
223	    /// Returns the current buffer. Only useful for debugging.
224	    #[cfg(test)]
225	    pub fn buffer(&self) -> &[u8] {
226	        &self.buffer
227	    }
228	}
229	
230	impl<W, D> Write for Writer<W, D>
231	where
232	    W: Write,
233	    D: Operation,
234	{
235	    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
236	        if self.finished {
237	            return Err(io::Error::new(
238	                io::ErrorKind::Other,
239	                "encoder is finished",
240	            ));
241	        }
242	        // Keep trying until _something_ has been consumed.
243	        // As soon as some input has been taken, we cannot afford
244	        // to take any chance: if an error occurs, the user couldn't know
245	        // that some data _was_ successfully written.
246	        loop {
247	            // First, write any pending data from `self.buffer`.
248	            self.write_from_offset()?;
249	            // At this point `self.buffer` can safely be discarded.
250	
251	            // Support writing concatenated frames by re-initializing the
252	            // context.
253	            if self.finished_frame {
254	                self.operation.reinit()?;
255	                self.finished_frame = false;
256	            }
257	
258	            let mut src = InBuffer::around(buf);
259	            let hint = self.with_buffer(|dst, op| op.run(&mut src, dst));
260	            let bytes_read = src.pos;
261	
262	            // eprintln!(
263	            //     "Write Hint: {:?}\n src: {:?}\n dst: {:?}",
264	            //     hint, src, self.buffer
265	            // );
266	
267	            self.offset = 0;
268	            let hint = hint?;
269	
270	            if hint == 0 {
271	                self.finished_frame = true;
272	            }
273	
274	            // As we said, as soon as we've consumed something, return.
275	            if bytes_read > 0 || buf.is_empty() {
276	                // println!("Returning {}", bytes_read);
277	                return Ok(bytes_read);
278	            }
279	        }
280	    }
281	
282	    fn flush(&mut self) -> io::Result<()> {
283	        let mut flushed = self.finished;
284	        loop {
285	            // If the output is blocked or has an error, return now.
286	            self.write_from_offset()?;
287	
288	            if flushed {
289	                break;
290	            }
291	
292	            if self.finish_requested {
293	                // A finish was requested but did not complete (the writer
294	                // blocked halfway through the frame trailer, for instance).
295	                // Keep closing the frame instead of starting a regular
296	                // flush: the operation must not be taken back to a state
297	                // where new data could be compressed.
298	                self.finish_step()?;
299	                flushed = self.finished;
300	            } else {
301	                let hint = self.with_buffer(|dst, op| op.flush(dst));
302	
303	                self.offset = 0;
304	                let hint = hint?;
305	
306	                flushed = hint == 0;
307	            }
308	        }
309	
310	        self.writer.flush()
311	    }
312	}
