    // Resume through do_finish.
    let mut decoder = Decoder::new(ThrottledWriter::new(usize::MAX)).unwrap();
    decoder.write_all(&compressed).unwrap();
    decoder.get_mut().allow(2);
    let err = decoder.do_finish().unwrap_err();
